parameters.jsonBody:
{
  "tool_config": {
    "type": "webhook",
    "name": "get_indicative_quote",
    "description": "Select the best Unica retail product and return an indicative annual price range. Call once the line_of_business and that line's mandatory fields are known.",
    "response_timeout_secs": 20,
    "api_schema": {
      "url": "https://ai-process.app.n8n.cloud/webhook/unica-qualify",
      "method": "POST",
      "request_body_schema": {
        "type": "object",
        "required": ["line_of_business"],
        "properties": {
          "line_of_business": { "type": "string", "description": "One of: car, liability, home_contents, legal, life" },
          "name": { "type": "string", "description": "Caller name" },
          "email": { "type": "string", "description": "Caller email" },
          "phone": { "type": "string", "description": "Caller phone" },
          "region": { "type": "string", "description": "wien, graz, linz or land" },
          "consent_recording": { "type": "boolean", "description": "Did the caller consent to recording" },
          "coverage": { "type": "string", "description": "car only: haftpflicht, teilkasko or vollkasko" },
          "driver_age": { "type": "number", "description": "car only: age of main driver" },
          "power_kw": { "type": "number", "description": "car only: engine power in kW" },
          "bonus_malus": { "type": "number", "description": "car only: 0.5 best to 1.8 worst" },
          "household": { "type": "string", "description": "liability only: single or family" },
          "contents_value": { "type": "number", "description": "home_contents only: sum insured in EUR" },
          "sum_assured": { "type": "number", "description": "life only: cover amount in EUR" },
          "term_years": { "type": "number", "description": "life only: term length in years" },
          "tobacco": { "type": "boolean", "description": "life only: is the person a smoker" }
        }
      }
    }
  }
}
